charts/matrix-app/templates/deployment.y.content:
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "matrix-app.fullname" . }}
  labels: {{ include "matrix-app.labels" . | nindent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      app.kubernetes.io/name: matrix-app
      app.kubernetes.io/instance: {{ .Release.Name }}
  template:
    metadata:
      labels: {{ include "matrix-app.labels" . | nindent 8 }}
    spec:
      automountServiceAccountToken: false
      securityContext:
        runAsNonRoot: true
        seccompProfile: {type: RuntimeDefault}
      containers:
        - name: extension
{{ if .Values.image.digest }}
          image: "{{ .Values.image.repository }}@{{ .Values.image.digest }}"
{{ else }}
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
{{ end }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          env:
            - {name: SCAFFOLD_HTTP, value: "true"}
          ports:
            - {name: http, containerPort: 8080}
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities: {drop: [ALL]}
          readinessProbe:
            httpGet: {path: /healthz, port: http}
            periodSeconds: 2
            failureThreshold: 15
          livenessProbe:
            httpGet: {path: /healthz, port: http}
            periodSeconds: 10
          resources: {{ .Values.resources | toYaml | nindent 12 }}

charts/matrix-app/templates/service.yaml.content:
apiVersion: v1
kind: Service
metadata:
  name: {{ include "matrix-app.fullname" . }}
  labels: {{ include "matrix-app.labels" . | nindent 4 }}
spec:
  type: {{ .Values.service.type }}
  selector:
    app.kubernetes.io/name: matrix-app
    app.kubernetes.io/instance: {{ .Release.Name }}
  ports:
    - name: http
      port: {{ .Values.service.port }}
      targetPort: http

extension/cmd/matrix-app/main.go.content:
package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"time"

	scaffold "github.com/7K-Hiroba/matrix-app"
)

func main() {
	if os.Getenv("SCAFFOLD_HTTP") == "true" {
		server := &http.Server{
			Addr:              ":8080",
			Handler:           scaffold.HTTPHandler(),
			ReadHeaderTimeout: 5 * time.Second,
			ReadTimeout:       10 * time.Second,
			WriteTimeout:      10 * time.Second,
			IdleTimeout:       30 * time.Second,
		}
		log.Printf("synthetic smoke server listening on %s", server.Addr)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatal(err)
		}
		return
	}
	if err := scaffold.New().Serve(context.Background()); err != nil {
		log.Fatal(err)
	}
}

extension/extension.go.content:
// Package scaffold implements the public-SDK extension used by workflow tests.
package scaffold

import (
	"context"

	pluginsdk "github.com/7K-Inari/inari-plugin-sdk"
)

const (
	Name    = "matrix-app"
	Version = "0.1.0"
)

// New returns the extension with its single read-only action.
func New() *pluginsdk.Plugin {
	plugin := pluginsdk.New(pluginsdk.Info{Name: Name, Version: Version})
	if err := plugin.RegisterAction(pluginsdk.Action{
		Name:        "scaffold.ping",
		Description: "Return a synthetic health response",
		Handler: func(context.Context, *pluginsdk.Request) (*pluginsdk.Response, error) {
			return &pluginsdk.Response{Result: []byte(`{"status":"ok"}`)}, nil
		},
	}); err != nil {
		panic(err)
	}
	return plugin
}

extension/extension_test.go.content:
package scaffold

import (
	"context"
	"testing"

	pluginsdk "github.com/7K-Inari/inari-plugin-sdk"
	"github.com/7K-Inari/inari-plugin-sdk/testkit"
)

func TestPublicContract(t *testing.T) {
	client := testkit.Run(t, New())
	ctx := context.Background()
	info, err := client.Info(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if info.GetName() != Name || info.GetApiVersion() != "inari.plugin.v1" {
		t.Fatalf("unexpected info: %+v", info)
	}
	actions, err := client.Capabilities(ctx)
	if err != nil || len(actions) != 1 || actions[0].GetName() != "scaffold.ping" {
		t.Fatalf("unexpected capabilities: %+v, %v", actions, err)
	}
	response, err := client.Invoke(ctx, "scaffold.ping", pluginsdk.AuthContext{PrincipalID: "ci", TenantID: "org:ci"}, nil)
	if err != nil || string(response.Result) != `{"status":"ok"}` {
		t.Fatalf("unexpected response: %+v, %v", response, err)
	}
	serving, _, err := client.Health(ctx)
	if err != nil || !serving {
		t.Fatalf("health: serving=%v err=%v", serving, err)
	}
}

extension/http.go.content:
package scaffold

import "net/http"

// HTTPHandler exposes only synthetic endpoints for the ephemeral chart/smoke lane.
func HTTPHandler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writer.Header().Set("Content-Type", "text/plain")
		_, _ = writer.Write([]byte("ok\n"))
	})
	mux.HandleFunc("GET /api/ping", func(writer http.ResponseWriter, _ *http.Request) {
		writer.Header().Set("Content-Type", "application/json")
		_, _ = writer.Write([]byte(`{"status":"ok"}` + "\n"))
	})
	return mux
}

extension/http_test.go.content:
package scaffold

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestHTTPHandler(t *testing.T) {
	for _, path := range []string{"/healthz", "/api/ping"} {
		recorder := httptest.NewRecorder()
		HTTPHandler().ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, path, nil))
		if recorder.Code != http.StatusOK {
			t.Fatalf("%s returned %d", path, recorder.Code)
		}
	}
}

