import type { ComponentType } from 'react';
import { ClusterTabBlueprint, createExtension } from '@7k-inari/ui-plugin-sdk';
import type { ClusterTabSlotProps } from '@7k-inari/ui-plugin-sdk';

const Health: ComponentType<ClusterTabSlotProps> = () => (
  <section data-inari-slot="health" aria-label="Scaffold health">Synthetic extension healthy</section>
);

export default createExtension({
  manifest: {
    name: 'matrix-app',
    version: '0.1.0',
    kind: 'ui',
    title: 'Workflows scaffold',
    description: 'CI-only public SDK fixture',
  },
  slots: [ClusterTabBlueprint({ name: 'health', title: 'Health', component: Health })],
});

ui/tests/browser.spec.ts.content:
import { expect, test } from '@playwright/test';

test('slot cluster-tab:health', async ({ page }) => {
  const baseURL = process.env.INARI_UI_URL;
  const remoteEntry = process.env.INARI_REMOTE_ENTRY;
  test.skip(!baseURL || !remoteEntry, 'requires the pinned stable UI host and OCI-built remote supplied by compat-check');
  const errors: string[] = [];
  page.on('pageerror', (error) => errors.push(error.message));

  await page.goto(`${baseURL}/acme/extensions`);
  await page.locator('#ext-name').fill('matrix-app');
  await page.locator('#ext-entry').fill(remoteEntry!);
  await page.getByRole('button', { name: 'Add remote', exact: true }).click();
  await expect(page.locator('tr', { hasText: 'matrix-app' }).getByText('ready', { exact: true })).toBeVisible();

  await page.getByRole('link', { name: 'Clusters', exact: true }).click();
  await page.locator('table a[href*="/clusters/"]').first().click();
  await page.getByRole('tab', { name: 'Health', exact: true }).click();
  await expect(page.locator('[data-inari-slot="health"]')).toBeVisible();
  expect(errors).toEqual([]);
});

